import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 Lua 解析配置文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Lua 解析配置文件 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Lua 解析配置文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Lua 解析配置文件 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210623 Parsing config files with Lua","title":"使用 Lua 解析配置文件","tag":"202211","desc":""},"relativePath":"202211/20210623 Parsing config files with Lua.md","filePath":"[post].md"}'),c={name:"202211/20210623 Parsing config files with Lua.md"};function u(h,s,g,k,f,b){const n=o("Link");return r(),d("div",null,[s[35]||(s[35]=l('<h1 id="使用-lua-解析配置文件" tabindex="-1">使用 Lua 解析配置文件 <a class="header-anchor" href="#使用-lua-解析配置文件" aria-label="Permalink to “使用 Lua 解析配置文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/10/084609uq6vvp1vjzqzpc9k.jpg" alt=""></p><blockquote><p>使用 Lua 配置持久化应用设置。</p></blockquote><p>不是所有的应用都需要配置文件；对很多应用来说，在启动时变得焕然一新对它们更有利。例如，简单的工具就极少需要偏好项和设置在使用过程中保持稳定不变。然而，当你编写一个复杂的应用程序时，如果能让用户设置与应用的交互方式，以及应用与系统交互的方式会很不错。这就是配置文件用来做的事情。本文将讨论一些利用 Lua 进行持久化配置的方法。</p><h3 id="选择一种格式" tabindex="-1">选择一种格式 <a class="header-anchor" href="#选择一种格式" aria-label="Permalink to “选择一种格式”">​</a></h3><p>关于配置文件很重要的两点是一致性和可预见性。你不会希望为了保存用户偏好项，将信息转储到文件中，然后再花几天去编码实现“逆向工程”，处理最后出现在文件里的随机信息。</p>',6)),i("p",null,[s[1]||(s[1]=a("这里用一些常用的 ",-1)),e(n,{href:"https://opensource.com/article/21/6/config-files-and-their-formats"},{default:p(()=>[...s[0]||(s[0]=[a("配置文件格式",-1)])]),_:1}),s[2]||(s[2]=a("。Lua 有一些库可以处理大多数常用的配置格式；在本文中，我会采用 INI 格式。",-1))]),s[36]||(s[36]=i("h3",{id:"安装库",tabindex:"-1"},[a("安装库 "),i("a",{class:"header-anchor",href:"#安装库","aria-label":"Permalink to “安装库”"},"​")],-1)),i("p",null,[s[4]||(s[4]=a("Lua 库的核心仓库是 ",-1)),e(n,{href:"https://opensource.com/article/19/11/getting-started-luarocks"},{default:p(()=>[...s[3]||(s[3]=[a("Luarocks.org",-1)])]),_:1}),s[5]||(s[5]=a("。你可以在这个网站搜索库，或者你可以安装并使用 ",-1)),s[6]||(s[6]=i("code",null,"luarocks",-1)),s[7]||(s[7]=a(" 终端命令。",-1))]),s[37]||(s[37]=l('<p>Linux 环境中，你可以从发行版的软件仓库中下载它，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install luarocks</span></span></code></pre></div>',2)),i("p",null,[s[11]||(s[11]=a("在 macOS 上，请使用 ",-1)),e(n,{href:"https://opensource.com/article/20/11/macports"},{default:p(()=>[...s[8]||(s[8]=[a("MacPorts",-1)])]),_:1}),s[12]||(s[12]=a(" 或者 ",-1)),e(n,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:p(()=>[...s[9]||(s[9]=[a("Homebrew",-1)])]),_:1}),s[13]||(s[13]=a("。在 Windows 上，请使用 ",-1)),e(n,{href:"https://opensource.com/article/20/3/chocolatey"},{default:p(()=>[...s[10]||(s[10]=[a("Chocolatey",-1)])]),_:1}),s[14]||(s[14]=a("。",-1))]),s[38]||(s[38]=l(`<p><code>luarocks</code> 安装后，你可以使用 <code>search</code> 子命令来搜索一个恰当的库。如果你不知道库的名字，可以通过关键词来搜索这个库，例如 <code>ini</code>、xml<code>或者</code>json<code>，这取决于你想要用这个库做什么。打个比方，你可以搜索 </code>inifile\`， 这个库被我用来解析 INI 格式的文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ luarocks search inifile</span></span>
<span class="line"><span>Search results:</span></span>
<span class="line"><span>inifile</span></span>
<span class="line"><span> 1.0-2 (rockspec) - https://luarocks.org</span></span>
<span class="line"><span> 1.0-2 (src) - https://luarocks.org</span></span>
<span class="line"><span> 1.0-1 (rockspec) - https://luarocks.org</span></span>
<span class="line"><span> [...]</span></span></code></pre></div><p>一个开发者容易犯的错误是在系统上安装了这个库却忘了把它和应用打包。这会给没有安装这个库的用户带来麻烦。为了防止这个问题发生，可以使用 <code>--tree</code> 选项将它安装在项目的本地文件夹中。如果你没有这个项目文件夹，那就先创建这个文件夹再安装库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir demo</span></span>
<span class="line"><span>$ cd demo</span></span>
<span class="line"><span>$ luarocks install --tree=local inifile</span></span></code></pre></div><p><code>--tree</code> 选项指示 <code>luarocks</code> 创建一个新文件夹并在其中安装你的库，例如这个例子中的 <code>local</code> 文件夹。 使用这个简单的技巧，你可以将所有你项目要使用的依赖项直接安装到项目文件夹中。</p><h3 id="配置代码" tabindex="-1">配置代码 <a class="header-anchor" href="#配置代码" aria-label="Permalink to “配置代码”">​</a></h3><p>首先，在一个名 <code>myconfig.ini</code> 的文件中创建一些 INI 数据。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[example]</span></span>
<span class="line"><span>name=Tux</span></span>
<span class="line"><span>species=penguin</span></span>
<span class="line"><span>enabled=false</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[demo]</span></span>
<span class="line"><span>name=Beastie</span></span>
<span class="line"><span>species=demon</span></span>
<span class="line"><span>enabled=false</span></span></code></pre></div><p>将这个文件保存到你的主目录下，命名为 <code>myconfig.ini</code>, <em>不要</em> 存到项目文件夹下。你通常会希望配置文件独立于你的文件存在，这样当用户卸载你的应用时，使用应用时产生的数据可以保存在系统中。有些用户会删除不重要的配置文件，但大多数不会。最终，如果他们要重装这个应用，还会保留着所有的用户偏好项。</p>`,9)),i("p",null,[s[16]||(s[16]=a("配置文件的位置以技术来说并不重要，但每一个操作系统都有存储它们的特定或者默认的路径。在 Linux 中，这个路径由 ",-1)),e(n,{href:"https://www.freedesktop.org/wiki/Specifications"},{default:p(()=>[...s[15]||(s[15]=[a("Freedesktop 规范",-1)])]),_:1}),s[17]||(s[17]=a(" 指定。它规定配置文件被保存在一个名为 ",-1)),s[18]||(s[18]=i("code",null,"~/.config",-1)),s[19]||(s[19]=a(" 的隐藏文件夹中。为了操作时更加清晰明确，可以在主目录下存储配置文件，以便于使用和寻找。",-1))]),s[39]||(s[39]=l(`<p>创建第二个文件，命名为 <code>main.lua</code>，并在你喜欢的文本编辑器中打开它。</p><p>首先，你必须告诉 Lua 你将想要使用的附加库放置在哪里。<code>package.path</code> 变量决定了 Lua 到哪里去寻找这些库。你可以从终端中查看 Lua 默认的包地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Lua</span></span>
<span class="line"><span>&gt; print(package.path)</span></span>
<span class="line"><span>./?.lua;/usr/share/lua/5.3/?.lua;/usr/share/lua/5.3/?/init.lua;/usr/lib64/lua/5.3/?.lua;/usr/lib64/lua/5.3/?/init.lua</span></span></code></pre></div><p>在你的 Lua 代码中，将你本地库的路径添加到 <code>package.path</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua</span></span></code></pre></div><h3 id="使用-lua-解析-ini-文件" tabindex="-1">使用 Lua 解析 INI 文件 <a class="header-anchor" href="#使用-lua-解析-ini-文件" aria-label="Permalink to “使用 Lua 解析 INI 文件”">​</a></h3><p>当包的位置确定以后，下一件事就是引入 <code>inifile</code> 库并处理一些操作系统逻辑。即使这是一个很简单的应用，代码也需要从操作系统获取到用户主目录的路径，并建立在必要时将文件系统路径返回给操作系统的通信方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua</span></span>
<span class="line"><span>inifile = require(&#39;inifile&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- find home directory</span></span>
<span class="line"><span>home = os.getenv(&#39;HOME&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- detect path separator</span></span>
<span class="line"><span>-- returns &#39;/&#39; for Linux and Mac</span></span>
<span class="line"><span>-- and &#39;\\&#39; for Windows</span></span>
<span class="line"><span>d = package.config:sub(1,1)</span></span></code></pre></div><p>现在你可使用 <code>inifile</code> 来从配置文件解析数据到 Lua 表中。一旦这些数据被导入进表中，你可以像查询其他的 Lua 表一样查询它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-- parse the INI file and</span></span>
<span class="line"><span>-- put values into a table called conf</span></span>
<span class="line"><span>conf = inifile.parse(home .. d .. &#39;myconfig.ini&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- print the data for review</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;name&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;species&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;enabled&#39;])</span></span></code></pre></div><p>在终端中运行代码可以看见结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./main.lua</span></span>
<span class="line"><span>Tux</span></span>
<span class="line"><span>penguin</span></span>
<span class="line"><span>false</span></span></code></pre></div><p>这看起来是正确的。试试在 <code>demo</code> 块中执行同样的操作。</p><h3 id="使用-ini-格式存储数据" tabindex="-1">使用 INI 格式存储数据 <a class="header-anchor" href="#使用-ini-格式存储数据" aria-label="Permalink to “使用 INI 格式存储数据”">​</a></h3><p>不是所有用来解析的库都会读写数据（通常被称为 _编码 和 <em>解码</em>），但是 <code>inifile</code> 会这样做。这意味着你可以使用它对配置文件进行修改。</p><p>为了改变配置文件中的值，你可以对被解析的表中的变量进行设置，然后把表重写回配置文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-- set enabled to true</span></span>
<span class="line"><span>conf[&#39;example&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span>conf[&#39;demo&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- save the change</span></span>
<span class="line"><span>inifile.save(home .. d .. &#39;myconfig.ini&#39;, conf)</span></span></code></pre></div><p>现在再来看看配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/myconfig.ini</span></span>
<span class="line"><span>[example]</span></span>
<span class="line"><span>name=Tux</span></span>
<span class="line"><span>species=penguin</span></span>
<span class="line"><span>enabled=true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[demo]</span></span>
<span class="line"><span>name=Beastie</span></span>
<span class="line"><span>species=demon</span></span>
<span class="line"><span>enabled=true</span></span></code></pre></div><h3 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to “配置文件”">​</a></h3><p>按照用户的设想来存储数据对程序来说是至关重要的。幸运的是，这对工程师来说是一个很常规的任务，大多数工作可能早已被完成了。只要找到一个好用的库完成开放格式下编码和解码，你就能为用户提供一致且持续的体验。</p><p>以下是完整的演示代码，可供参考。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua&#39;</span></span>
<span class="line"><span>inifile = require(&#39;inifile&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- find home directory</span></span>
<span class="line"><span>home = os.getenv(&#39;HOME&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- detect path separator</span></span>
<span class="line"><span>-- returns &#39;/&#39; for Linux and Mac</span></span>
<span class="line"><span>-- and &#39;\\&#39; for Windows</span></span>
<span class="line"><span>d = package.config:sub(1,1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- parse the INI file and</span></span>
<span class="line"><span>-- put values into a table called conf</span></span>
<span class="line"><span>conf = inifile.parse(home .. d .. &#39;myconfig.ini&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- print the data for review</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;name&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;species&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;enabled&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- enable Tux</span></span>
<span class="line"><span>conf[&#39;example&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- save the change</span></span>
<span class="line"><span>inifile.save(home .. d .. &#39;myconfig.ini&#39;, conf)</span></span></code></pre></div><hr>`,24)),i("p",null,[s[21]||(s[21]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/6/parsing-config-files-lua"},{default:p(()=>[...s[20]||(s[20]=[a("https://opensource.com/article/21/6/parsing-config-files-lua",-1)])]),_:1})]),i("p",null,[s[26]||(s[26]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[22]||(s[22]=[a("Seth Kenlon",-1)])]),_:1}),s[27]||(s[27]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[23]||(s[23]=[a("lujun9972",-1)])]),_:1}),s[28]||(s[28]=a(" 译者：",-1)),e(n,{href:"https://github.com/hadisi1993"},{default:p(()=>[...s[24]||(s[24]=[a("hadisi1993",-1)])]),_:1}),s[29]||(s[29]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[25]||(s[25]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[32]||(s[32]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[30]||(s[30]=[a("LCTT",-1)])]),_:1}),s[33]||(s[33]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[31]||(s[31]=[a("Linux中国",-1)])]),_:1}),s[34]||(s[34]=a(" 荣誉推出",-1))])])}const C=t(c,[["render",u]]);export{y as __pageData,C as default};
